<?php
require_once __DIR__.'/includes/bootstrap.php';require_auth();if(!can_manage()){http_response_code(403);exit('Accès refusé.');}$page_title='Nouveau dépôt';
$clients=db()->query("SELECT id,nom,prenom,telephone FROM clients ORDER BY nom")->fetchAll();$services=db()->query("SELECT t.id AS tarif_id, CONCAT(s.nom, ' · ', ta.nom) AS libelle, t.prix FROM tarifs t JOIN services s ON s.id = t.service_id JOIN types_articles ta ON ta.id = t.type_article_id WHERE s.actif = 1 AND ta.actif = 1 AND t.date_effet = (SELECT MAX(t2.date_effet) FROM tarifs t2 WHERE t2.service_id = t.service_id AND t2.type_article_id = t.type_article_id AND t2.date_effet <= CURDATE()) ORDER BY s.nom, ta.nom")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$client=(int)$_POST['client_id'];$type=$_POST['type_depot']==='express'?'express':'normal';$date=$_POST['date_prevue'];$ids=$_POST['tarif_id']??[];$qty=$_POST['quantite']??[];$descs=$_POST['description']??[];if(!$ids||!$client){flash('Choisissez un client et au moins un service.','error');redirect('order_new.php');}
$pdo=db();$pdo->beginTransaction();try{$code='PR-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));$pdo->prepare("INSERT INTO commandes(reference,client_id,depose_par,type_depot,date_promise,notes) VALUES(?,?,?,?,?,?)")->execute([$code,$client,$_SESSION['user']['id'],$type,$date,$_POST['notes']??'']);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO commande_lignes(commande_id,tarif_id,description,quantite) VALUES(?,?,?,?)");foreach($ids as $i=>$sid){if((int)$sid<1)continue;$q=max(1,(int)($qty[$i]??1));$ins->execute([$oid,(int)$sid,trim($descs[$i]??''),$q]);}$pdo->commit();flash('Dépôt créé : '.$code);redirect('order_view.php?id='.$oid);}catch(Throwable $e){$pdo->rollBack();flash('Erreur lors de la création du dépôt.','error');redirect('order_new.php');}}
require 'includes/header.php';?>
<div class="form-card"><form method="post" id="orderForm"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="form-grid"><div class="field"><label>Client *</label><select name="client_id" required><option value="">Sélectionner un client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['prenom'].' '.$c['nom'].' · '.$c['telephone'])?></option><?php endforeach;?></select><?php if(!$clients):?><small>Ajoutez d'abord un client dans le menu Clients.</small><?php endif;?></div><div class="field"><label>Type de dépôt</label><select name="type_depot"><option value="normal">Normal</option><option value="express">Express (+<?=EXPRESS_SURCHARGE_PERCENT?>%)</option></select></div><div class="field"><label>Date prévue de retrait</label><input type="date" name="date_prevue" min="<?=date('Y-m-d')?>" value="<?=date('Y-m-d',strtotime('+2 days'))?>" required></div><div class="field"><label>Note interne</label><input name="notes" placeholder="Informations complémentaires"></div></div><hr style="border:0;border-top:1px solid #e7ebf3;margin:22px 0"><h2>Articles et prestations</h2><p class="muted">Tarifs indicatifs en FCFA. Le dépôt express applique une majoration de <?=EXPRESS_SURCHARGE_PERCENT?>% pour mieux couvrir l'urgence et préserver votre marge.</p><?php for($i=0;$i<3;$i++):?><div class="form-grid" style="margin-bottom:13px"><div class="field"><label>Prestation</label><select name="tarif_id[]"><option value="">— Aucun —</option><?php foreach($services as $s):?><option value="<?=$s['tarif_id']?>"><?=e($s['libelle'])?> · <?=money($s['prix'])?></option><?php endforeach;?></select></div><div class="field"><label>Quantité</label><input type="number" name="quantite[]" min="1" value="1"></div><div class="field full"><label>Description des vêtements (ex. chemises, pantalons)</label><input name="description[]" placeholder="Description"></div></div><?php endfor;?><button class="btn" type="submit" <?=!$clients||!$services?'disabled':''?>>Créer le dépôt</button> <a class="btn light" href="orders.php">Annuler</a></form></div>
<?php require 'includes/footer.php';?>
